variables.query:
query SearchTemplatesAdvanced($filter: QueryTemplatesFilter, $pagination: PaginationInput, $sort: [SortInput!]) {
  searchTemplates(filter: $filter, pagination: $pagination, sort: $sort) {
    templates {
      id
      identifier
      name
      description
      tags
      isActive
      usageCount
      avgExecutionTimeMs
      lastUsedAt
      createdAt
      updatedAt
    }
    totalCount
    hasMore
  }
}
